#include <iostream> // for the test harness
#include <initializer_list>
#include <algorithm>
template <typename T, int S = 1>
class DynamArr {
private:
    T* value;
public:
    int length;
    DynamArr(std::initializer_list<T> init) {
        this->length = S > 1 ? S : init.size();
        this->value = new T[this->length];
        std::copy(init.begin(), init.end(), this->value);
    }
    DynamArr() {
        this->length = S > 1 ? S : 1;
        this->value = new T[this->length];
    }
    T& operator[](size_t index) {
        return this->value[index];
    }
    const T& operator[](size_t index) const {
        return this->value[index];
    }
    const T back() const {
        return this->value[this->length - 1];
    }
    const T front() const {
        return this->value[0];
    }
    const T* data() const {
        return this->value;
    }
    ~DynamArr() {
        delete[] this->value;
        this->value = nullptr;
    }
};

runHarness:
int _pass = 0;
int _fail = 0;

void _test(int num, int got, int expected) {
    bool passed = got == expected;
    std::cout << "---------------------\n";
    std::cout << "Test " << num << ":\n";
    std::cout << (passed ? "Pass" : "Fail") << "\n";
    if (passed) _pass++; else _fail++;
}

int main() {
    DynamArr<int, 1> tester;
    tester.push(21);
    tester.push(-1);
    _test(1, 2, tester.length);
    _test(2, 21, tester.data()[0]);
    _test(3, -1, tester.data()[1]);
    std::cout << "---------------------\n";
    std::cout << _pass << " passed, " << _fail << " failed\n";
    return 0;
}
